class ExperienceCollector:
    def collect_all(self, max_samples=100_000):
        records = []
        # Tier 1: Parquet (fastest)
        try:
            records.extend(self._collect_parquet(max_samples))
        except Exception as e:
            logger.warning(f"Parquet collection failed: {e}")
        # Tier 2: SurrealDB (medium)
        try:
            remaining = max_samples - len(records)
            if remaining > 0:
                records.extend(self._collect_surreal(remaining))
        except Exception as e:
            logger.warning(f"SurrealDB collection failed: {e}")
        # Tier 3: Vault JSON (slowest, always available)
        try:
            remaining = max_samples - len(records)
            if remaining > 0:
                records.extend(self._collect_vault(remaining))
        except Exception as e:
            logger.warning(f"Vault collection failed: {e}")
        return records
